const FOCUSABLE=["a[href]","button:not([disabled])","input:not([disabled])","select:not([disabled])","textarea:not([disabled])","[tabindex]:not([tabindex='-1'])",].join(", ");export function trap(dialog,event){if(event.key!=="Tab")return;const items=[...dialog.querySelectorAll(FOCUSABLE)];const first=items[0];const last=items[items.length-1];if(first===undefined||last===undefined){event.preventDefault();return;}
const inside=items.includes(event.target);if(event.shiftKey&&(!inside||event.target===first)){event.preventDefault();last.focus();}else if(!event.shiftKey&&(!inside||event.target===last)){event.preventDefault();first.focus();}}
export function activate({dialog,button,closeButton}){dialog.setAttribute("data-enhanced","");button.hidden=false;if(closeButton!==undefined)closeButton.hidden=false;button.addEventListener("click",()=>{if(!dialog.open)dialog.showModal();button.setAttribute("aria-expanded","true");});closeButton?.addEventListener("click",()=>dialog.close());dialog.addEventListener("close",()=>{button.setAttribute("aria-expanded","false");button.focus();});dialog.addEventListener("keydown",(event)=>{if(event.key==="Escape"){event.preventDefault();dialog.close();return;}
trap(dialog,event);});}
if(typeof document!=="undefined"){const dialog=document.querySelector("[data-drawer]");const button=document.querySelector("[data-drawer-open]");if(dialog&&button){const closeButton=document.querySelector("[data-drawer] [data-drawer-close]");activate({dialog:dialog,button:button,...(closeButton?{closeButton:closeButton}:{}),});}}